node -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

// Look at orders table schema
const cols = db.prepare(\"PRAGMA table_info(orders)\").all();
console.log('orders columns:', cols.map(c => c.name));

// Find order with ORD-5B048F - let's see what IDs look like
const sample = db.prepare(\"SELECT * FROM orders LIMIT 3\").all();
console.log('Sample orders:', JSON.stringify(sample, null, 2));
" 2>&1

node -e "
const { DatabaseSync } = require('node:sqlite');
