console.log('Order Items:', JSON.stringify(items, null, 2));

// Get customer info
const user = db.prepare(\"SELECT * FROM users WHERE user_id = 'user_d3d5d0c8'\").all();
console.log('Customer:', JSON.stringify(user, null, 2));

// Get order payments
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-5B048F'\").all();
console.log('Payments:', JSON.stringify(payments, null, 2));

// Get order fulfillments
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-5B048F'\").all();
console.log('Fulfillments:', JSON.stringify(fulfillments, null, 2));
